function ReviewView({ state, update }: { state:DemoState; update:(p:Partial<DemoState>,m?:string)=>void }) {
  const [approved,setApproved]=useState<string[]>(state.managerApproved?["Acceptance & independence","Audit strategy & scope","Entity understanding","Internal controls","Materiality","Risk assessment","Audit responses","Adjustments & overrides"]:[]); const [note,setNote]=useState(""); const [reopen,setReopen]=useState(false);
  const materialityOverall=state.materialityOverride?240000:state.benchmark*(state.materialityPct/100);
  const performanceOverall=materialityOverall*(state.performancePct/100);
  const trivialOverall=materialityOverall*(state.trivialPct/100);
  const cards=[["Acceptance & independence","Continuance accepted · 2 team confirmations outstanding","warning"],["Audit strategy & scope","Standalone financial audit · 386 planned hours","good"],["Entity understanding","Validated narrative · 6 source documents","good"],["Internal controls","2 controls reliance planned · 1 design gap","warning"],["Materiality",`Overall ${money(materialityOverall)} · Performance ${money(performanceOverall)} · Trivial ${money(trivialOverall)}`,"good"],["Risk assessment","12 risks · 3 High · Revenue cutoff is top risk","good"],["Audit responses",state.responseGap?"91% coverage · 1 significant risk gap":"100% coverage · all significant risks covered",state.responseGap?"danger":"good"],["Adjustments & overrides","3 reconciliation issues accepted · $12,000 largest variance","warning"]];
  const canApprove=state.role==="Manager"||state.role==="Partner"||state.role==="Firm Administrator";
  const approve=(title:string)=>{if(!canApprove){update({},"Switch to Manager or Partner to approve conclusions");return;}setApproved(a=>[...new Set([...a,title])]);update({},`${title} approved at ${state.role} level`)};
  const all=approved.length===cards.length;
  return <div className="content-pad review-page"><div className="review-banner"><div><span className="status-pill progress">{state.locked?"Approved & locked":state.planningStatus}</span><h2>Manager / Partner roll-up</h2><p>Review each significant planning conclusion independently before locking Planning.</p></div><div className="reviewers"><span className={state.managerApproved?"done":"active"}><CheckCircle2/>Manager</span><i/><span className={state.partnerApproved?"done":state.managerApproved?"active":""}><ShieldCheck/>Partner</span></div></div>
    {!canApprove&&<Banner tone="info" title="Read-only preparer view" text="Switch the prototype role to Manager or Partner to demonstrate approval actions."/>}
    {cards.map(([title,detail,tone])=><article className={`review-card ${approved.includes(title)?"approved-card":""}`} key={title}><div className={`review-icon ${tone}`}>{approved.includes(title)?<Check/>:tone==="danger"?<AlertCircle/>:tone==="warning"?<AlertTriangle/>:<FileCheck2/>}</div><div><h3>{title}</h3><p>{detail}</p>{title==="Materiality"&&<small>Benchmark: Total Revenue (2.5%) · Source: reconciled Trial Balance</small>}{title==="Risk assessment"&&<small>3 significant · 2 fraud risks · all non-zero FSAs concluded</small>}</div><div className="review-actions">{approved.includes(title)?<span className="approved-by"><CheckCircle2/>Approved by {state.role}</span>:<><button className="secondary-btn" onClick={()=>{setNote(title);update({},"Review note opened — type a comment before returning")}}>Return</button><button className="primary-btn" onClick={()=>approve(title)}>Approve</button></>}</div></article>)}
    {note&&<div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><h2>Return {note}</h2><p>Your comment is retained in the audit trail.</p></div><button className="icon-btn" onClick={()=>setNote("")}><X/></button></div><Field label="Reviewer comment" required><textarea autoFocus placeholder="Describe the required change…"/></Field><div className="modal-actions"><button className="secondary-btn" onClick={()=>setNote("")}>Cancel</button><button className="primary-btn" onClick={()=>{setNote("");update({planningStatus:"Returned for Changes"},"Section returned to the preparer with a review note")}}>Return for changes</button></div></div></div>}
    <div className="approval-footer"><div>{all?<CheckCircle2/>:<AlertCircle/>}<span><strong>{approved.length} of {cards.length} cards approved</strong><small>{all?"All conclusions are ready for final approval.":"Final approval remains disabled until every card is reviewed."}</small></span></div>{state.locked?<button className="danger-btn" onClick={()=>setReopen(true)}><RotateCcw/>Reopen Planning</button>:<><button className="primary-btn" disabled={!all||(state.role==="Partner"&&!state.managerApproved)} onClick={()=>state.role==="Partner"?update({partnerApproved:true,locked:true,planningStatus:"Approved & Locked"},"Partner approval recorded. Planning locked and Fieldwork unlocked."):update({managerApproved:true,planningStatus:"Pending Partner Approval"},"Manager approval recorded. Sent to Partner for final approval.")}><LockKeyhole/>{state.role==="Partner"?"Approve all & lock Planning":"Approve all as Manager"}</button>{state.role==="Partner"&&!state.managerApproved&&<small style={{color:"var(--red)"}}>Manager approval is required before Partner approval.</small>}</>}</div>
    {reopen&&<ReopenModal update={update} close={()=>setReopen(false)}/>} 
  </div>;
}

